{
  "assessment": "The source packet provides a complete manuscript describing three impact regimes for cornstarch-water drops. The selected quantitative cluster focuses on the inertial-dilatant number (ID) and the unified force model, with two regimes (Regime 2 and Regime 3) distinguished by ID. The extraction includes the ID definition, the Reynolds-Darcy dilatant force model, the inertial force model, and the unified weighted force model. Controls are volume fraction, impact velocity, and characteristic shear rate; readouts are the impact force and the ratio of times. The source supports numeric controls and readouts, and the case is authoring-ready.",
  "case_authoring_ready": true,
  "source": {
    "citation": "Anahita Mobaseri, Inertia-Dilatancy Interplay Governs Shear Thickening Drop Impact, Physical Review Letters (2026), DOI:10.1103/fyx7-jb1d",
    "journal_doi": "10.1103/fyx7-jb1d",
    "arxiv_versioned_id": "2601.12642v1"
  },
  "paper_scope": "The paper studies the impact dynamics of cornstarch-water drops across a range of volume fractions (0.30-0.43) and impact velocities (0.5-7.2 m/s), identifying three regimes: inertial (Regime 1), dilatant (Regime 2), and inertial-dilatant (Regime 3). It presents a unified model combining inertial and dilatant forces with a time-dependent weighting function.",
  "mechanisms": [
    {
      "mechanism_id": "inertial_force_model",
      "statement": "The inertial impact force for liquid-like drops is described by F_i(t) = c A_0 sqrt(t) exp(-t/tau), with A_0 = rho U_0^{5/2} D_0^{3/2}.",
      "equations": [
        "F_i(t) = c A_0 sqrt(t) exp(-t/tau)",
        "A_0 = rho U_0^{5/2} D_0^{3/2}"
      ],
      "variable_names": ["F_i", "t", "c", "A_0", "rho", "U_0", "D_0", "tau"],
      "parameters": [
        {
          "name": "c_inertial",
          "value": 3.99,
          "uncertainty": "0.75 (source_unspecified)",
          "unit": "dimensionless",
          "role": "prefactor in inertial force model",
          "anchors": [
            {
              "line_start": 132,
              "line_end": 132,
              "support": "c = 3.99 ± 0.75, consistent with theoretical prediction c = 3√6/2 ≈ 3.67"
            }
          ]
        },
        {
          "name": "tau_ratio",
          "value": 1.88,
          "uncertainty": "0.05 (source_unspecified)",
          "unit": "dimensionless",
          "role": "proportionality constant between decay time and time of maximum force",
          "anchors": [
            {
              "line_start": 132,
              "line_end": 132,
              "support": "linear fit yields τ = a t_max^F with a = 1.88 ± 0.05"
            }
          ]
        }
      ],
      "anchors": [
        {
          "line_start": 126,
          "line_end": 129,
          "support": "Equation 1: F(t) = c A_0 sqrt(t) exp(-t/tau), with A_0 = rho U_0^{5/2} D_0^{3/2}"
        },
        {
          "line_start": 132,
          "line_end": 132,
          "support": "c = 3.99 ± 0.75, τ = a t_max^F with a = 1.88 ± 0.05"
        }
      ]
    },
    {
      "mechanism_id": "dilatant_force_model",
      "statement": "The dilatant impact force is given by F_d(t) ≈ A π r_c^3 (μ_w/κ) Δφ |dh/dt|, derived from the Reynolds-Darcy pore pressure equation.",
      "equations": [
        "F_d(t) ≈ A π r_c^3 (μ_w/κ) Δφ |dh/dt|",
        "P_f ≈ (μ_w/κ) Δφ r_c |dh/dt|",
        "κ = (1-φ)^3 a^2 / (180 φ^2)"
      ],
      "variable_names": ["F_d", "A", "r_c", "μ_w", "κ", "Δφ", "h", "t", "φ", "a"],
      "parameters": [
        {
          "name": "beta0_regime2",
          "value": 44,
          "uncertainty": "2 degrees (source_unspecified)",
          "unit": "degree",
          "role": "friction angle at critical volume fraction in Regime 2",
          "anchors": [
            {
              "line_start": 174,
              "line_end": 174,
              "support": "fitting yields β0 = 44 ± 2°, agreeing with repose angle of cornstarch powder"
            }
          ]
        },
        {
          "name": "beta0_regime3",
          "value": 41,
          "uncertainty": "5 degrees (source_unspecified)",
          "unit": "degree",
          "role": "friction angle at critical volume fraction in Regime 3",
          "anchors": [
            {
              "line_start": 232,
              "line_end": 232,
              "support": "β0 = 41 ± 5° consistent with that extracted from Regime (2)"
            }
          ]
        },
        {
          "name": "alpha_dilatancy",
          "value": 1,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "prefactor in dilatancy angle relation",
          "anchors": [
            {
              "line_start": 153,
              "line_end": 153,
              "support": "prefactor α ≈ 1"
            }
          ]
        },
        {
          "name": "phi_c",
          "value": 0.37,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "critical volume fraction for discontinuous shear thickening",
          "anchors": [
            {
              "line_start": 153,
              "line_end": 153,
              "support": "φ_c is constant at about 0.37 at sufficiently high shear rates"
            },
            {
              "line_start": 217,
              "line_end": 217,
              "support": "boundary between Regime (1) and Regimes (2) and (3) is determined by φ_c ≈ 0.37"
            }
          ]
