              "line_start": 153,
              "line_end": 153,
              "support": "μ_w = 1 mPa·s"
            }
          ]
        },
        {
          "name": "a_particle",
          "value": 1e-05,
          "uncertainty": "source_unspecified",
          "unit": "m",
          "role": "average diameter of cornstarch particles",
          "anchors": [
            {
              "line_start": 153,
              "line_end": 153,
              "support": "a ≈ 10 μm"
            }
          ]
        }
      ],
      "anchors": [
        {
          "line_start": 150,
          "line_end": 153,
          "support": "Reynolds-Darcy equation: ∇²P_f = (μ_w/κ) γ̇ tanΨ = (μ_w/κ) γ̇ α(φ-φ_c), with κ = (1-φ)^3 a^2/(180 φ^2), α ≈ 1, φ_c ≈ 0.37"
        },
        {
          "line_start": 158,
          "line_end": 164,
          "support": "P_f ≈ (μ_w/κ) Δφ r_c |dh/dt|, leading to F(t) ≈ A π r_c^3 (μ_w/κ) Δφ |dh/dt|"
        },
        {
          "line_start": 174,
          "line_end": 174,
          "support": "fitting yields β0 = 44 ± 2°"
        }
      ]
    },
    {
      "mechanism_id": "inertial_dilatant_number",
      "statement": "The inertial-dilatant number ID = F_i/F_d = ρ κ U_0 / (A μ_w Δφ D_0) quantifies the competition between inertial and dilatant forces.",
      "equations": [
        "ID = ρ κ U_0 / (A μ_w Δφ D_0)"
      ],
      "variable_names": ["ID", "ρ", "κ", "U_0", "A", "μ_w", "Δφ", "D_0"],
      "parameters": [],
      "anchors": [
        {
          "line_start": 220,
          "line_end": 224,
          "support": "ID ≡ F_i/F_d = ρ κ U_0 / (A μ_w Δφ D_0)"
        }
      ]
    },
    {
      "mechanism_id": "unified_force_model",
      "statement": "The total impact force is a weighted sum of inertial and dilatant forces: F(t) = [1 - w_F(t)] F_i(t) + w_F(t) F_d(t), where w_F(t) is the solidified fraction.",
      "equations": [
        "F(t) = [1 - w_F(t)] F_i(t) + w_F(t) F_d(t)"
      ],
      "variable_names": ["F", "w_F", "F_i", "F_d", "t"],
      "parameters": [],
      "anchors": [
        {
          "line_start": 230,
          "line_end": 230,
          "support": "F(t) = [1 - w_F(t)] F_i(t) + w_F(t) F_d(t)"
        }
      ]
    }
